from flask import Flask, render_template, redirect, url_for

app = Flask(__name__)

STATIONS = [{'slug': 'columbus', 'name': 'Христофор Колумб', 'years': '1451–1506', 'tagline': 'Итальянский мореплаватель из Генуи', 'intro': 'Христофор Колумб — итальянский мореплаватель, родился в городе Генуя. С детства интересовался морем и путешествиями. Он мечтал найти новый морской путь из Европы в Азию, плывя на запад через Атлантический океан.', 'expeditions': ['1492 год — первая экспедиция. На трёх кораблях: «Санта-Мария», «Пинта» и «Нинья» пересёк Атлантический океан и достиг островов Карибского моря.', '1493–1496 годы — вторая экспедиция. Исследовал острова Карибского моря.', '1498–1500 годы — третья экспедиция. Достиг берегов Южной Америки, в районе устья реки Ориноко.', '1502–1504 годы — четвёртая экспедиция. Исследовал побережье Центральной Америки.'], 'significance': 'Колумб открыл для европейцев путь к землям Америки, но до конца жизни считал, что достиг берегов Азии.'}, {'slug': 'vespucci', 'name': 'Америго Веспуччи', 'years': '1454–1512', 'tagline': 'Исследователь нового материка', 'intro': 'Америго Веспуччи — итальянский путешественник, мореплаватель и исследователь. Родился во Флоренции. Участвовал в морских путешествиях к берегам Южной Америки и изучал новые земли.', 'expeditions': ['1499–1500 годы — путешествовал вдоль северного побережья Южной Америки, исследовал берега и острова.', '1501–1502 годы — исследовал восточное побережье Южной Америки. Пришёл к выводу, что открытые земли не являются Азией, а представляют собой новый материк.'], 'significance': 'Веспуччи одним из первых понял, что открытые земли — это новый материк. Позже в честь него материк получил название Америка.'}, {'slug': 'cabral', 'name': 'Педру Алвариш Кабрал', 'years': '1500 год', 'tagline': 'Побережье Бразилии', 'intro': 'Португальская экспедиция под руководством Педру Алвариша Кабрала в 1500 году достигла побережья территории современной Бразилии. Это событие стало важным этапом в истории европейского освоения восточной части Южной Америки.', 'significance': 'С экспедицией Кабрала связывают начало португальского присутствия на территории современной Бразилии.', 'expeditions': []}, {'slug': 'humboldt', 'name': 'Александр фон Гумбольдт', 'years': '1799–1804 годы', 'tagline': 'Учёный-естествоиспытатель', 'intro': 'Александр фон Гумбольдт вместе с Эме Бонпланом исследовал районы Южной Америки. Учёные изучали климат, растения, высотную поясность, рельеф, реки и взаимосвязи в природе. Их работы стали важной основой научного изучения материка.', 'significance': 'Гумбольдт рассматривал природу как единую систему, в которой компоненты тесно связаны.', 'expeditions': []}, {'slug': 'darwin', 'name': 'Чарльз Дарвин', 'years': '1831–1836 годы', 'tagline': 'Путешествие на «Бигле»', 'intro': 'Во время кругосветного плавания на корабле «Бигль» Чарльз Дарвин посещал разные районы Южной Америки. Он наблюдал животных и растения, изучал геологическое строение, ископаемые остатки и изменения природы. Эти наблюдения позднее стали важными для развития его научных идей.', 'significance': 'Путешествие на «Бигле» было кругосветным, а наблюдения в Южной Америке сыграли важную роль в научной работе Дарвина.', 'expeditions': []}]

@app.route("/")
def index():
    return render_template("index.html", stations=STATIONS)

@app.route("/station/<slug>")
def station(slug):
    item = next((s for s in STATIONS if s["slug"] == slug), None)
    if not item:
        return redirect(url_for("index"))
    return render_template("station.html", station=item, stations=STATIONS)

if __name__ == "__main__":
    app.run(debug=True)
